// Obtener la respuesta completa del agente de IA
const fullMessage = $input.first().json.responseText;
const messageObject = {
  MessagePart1: '',
  MessagePart2: '',
  MessagePart3: '',
};

// --- Lógica de Validación de Longitud ---
const SPLIT_THRESHOLD = 400;

if (!fullMessage || fullMessage.length <= SPLIT_THRESHOLD) {
  // Si el mensaje es corto, ponlo todo en la Parte 1.
  messageObject.MessagePart1 = fullMessage || '';
} else {
  // --- NUEVA LÓGICA DE DIVISIÓN POR PÁRRAFOS ---

  // 1. Dividir el texto en "bloques" usando los saltos de párrafo como delimitador.
  // La expresión regular /\n{2,}/ busca dos o más saltos de línea seguidos.
  // Se filtran los bloques vacíos que puedan resultar de la división.
  const blocks = fullMessage.split(/\n{2,}/).filter(block => block.trim() !== '');

  if (blocks.length <= 1) {
    // Si no se pudo dividir o solo hay un bloque, no segmentar.
    messageObject.MessagePart1 = fullMessage;
  } else {
    // 2. Agrupar los bloques en 3 partes, similar a la lógica anterior.
    const totalBlocks = blocks.length;
    const blocksPerPart = Math.ceil(totalBlocks / 3);

    for (let i = 0; i < 3; i++) {
      const start = i * blocksPerPart;
      const end = start + blocksPerPart;
      const partBlocks = blocks.slice(start, end);

      // 3. Unir los bloques de cada parte, RESTAURANDO los saltos de párrafo.
      const partText = partBlocks.join('\n\n').trim();
      messageObject['MessagePart' + (i + 1)] = partText;
    }
  }
}

// Devuelve un ÚNICO ítem con las tres claves
return [{ json: messageObject }];

// Obtenemos el resultado del nodo anterior (Date & Time).
// Asumimos que el número de días está en una clave llamada "days".
// ¡Asegúrate de que el nombre de la clave coincida con la salida real de tu nodo!
const numberOfDays = $input.first().json.timeDifference.days;

// Usamos Math.ceil() para redondear el número SIEMPRE hacia arriba al entero más cercano.
// Ejemplos:
// Math.ceil(9.95) devolverá 10
// Math.ceil(9.1) devolverá 10
// Math.ceil(9.0) devolverá 9
const roundedDays = Math.ceil(numberOfDays);

// Devolvemos el resultado en un nuevo objeto para usarlo en los siguientes nodos.
return {
  dias_cotizacion: roundedDays
};

