const cachedData = JSON.parse(inputItem.value);
const messages = cachedData.messages;

const finalOutput = [];
let i = 0;

while (i < messages.length) {
  const currentMessage = messages[i];

  if (currentMessage.type === 'text') {
    // Manejo de bloques de texto
    let textBuffer = [currentMessage.content];
    let nextIndex = i + 1;
    while (nextIndex < messages.length && messages[nextIndex].type === 'text') {
      textBuffer.push(messages[nextIndex].content);
      nextIndex++;
    }
    finalOutput.push({
      attachmentUrl: null,
      associatedText: textBuffer.join(' ')
    });
    i = nextIndex;

  } else if (currentMessage.type === 'attachment') { // <-- CAMBIO AQUÍ
    // Manejo de pares Adjunto -> Texto
    let associatedText = "";

    if ((i + 1) < messages.length && messages[i + 1].type === 'text') {
      associatedText = messages[i + 1].content;
      i++;
    }

    finalOutput.push({
      attachmentUrl: currentMessage.content, // <-- CAMBIO AQUÍ
      associatedText: associatedText
    });

    i++;
  } else {
    i++;
  }
}

return finalOutput.map(item => ({ json: item }));

