// Obtiene el string JSON de la salida del nodo anterior
const jsonString = $input.first().json.output;

// Convierte (parsea) el string en un objeto JSON real
const parsedJson = JSON.parse(jsonString);

// Devuelve el nuevo objeto JSON para que los siguientes nodos puedan usarlo
return [{ json: parsedJson }];

// --- CAPTURAMOS LAS ENTRADAS ---
const inputData = $input.first().json;
const megaJson = inputData.data[0]; 
const consolidatedArray = inputData.data[1].RangoEdadesIncremento;

// --- FUNCIÓN AUXILIAR PARA EXTRAER TABLAS DINÁMICAMENTE ---
// Esta función busca un ID (ej: "prices_T150V2") y extrae los días/precios que le siguen.
function getTableById(id) {
    const startIndex = consolidatedArray.findIndex(row => row["Rango Edades Incremento"] === id);
    if (startIndex === -1) return [];

    let rows = [];
    // Empezamos 2 filas después del ID (saltando el ID y el encabezado "dias/precio")
    for (let i = startIndex + 2; i < consolidatedArray.length; i++) {
        const row = consolidatedArray[i];
        const val = row["Rango Edades Incremento"];

        // Si encontramos el siguiente marcador de plan o una fila vacía, paramos
        if (typeof val === 'string' && val.startsWith('prices_')) break;
        if (val === undefined || val === null) break;

        rows.push({
            dias: parseInt(val),
            precio: parseFloat(row["__EMPTY"])
        });
    }
    return rows;
}

// --- PREPARAMOS LAS TABLAS ---

// 1. Extraer Incrementos por Edad (Asumimos que son las primeras filas de la tabla)
const ageIncrements = [];
for (let i = 1; i <= 4; i++) { // Filas 1 a 4 según tu JSON
    const row = consolidatedArray[i];
    ageIncrements.push({
        DESDE: parseInt(row["Rango Edades Incremento"]),
        HASTA: parseInt(row["__EMPTY"]),
        INCREMENTO: parseFloat(row["__EMPTY_1"])
    });
}

// 2. Mapear Tablas de Precios usando los marcadores del JSON
const priceTables = {
  "TRAVEL 150": getTableById("prices_T150V2"),
  "TRAVEL 100": getTableById("prices_T100V2"),
  "TRAVEL 50": getTableById("prices_T50V2"),
  "TRAVEL 25": getTableById("prices_T25V2"),
};

// --- LÓGICA DE RE-CÁLCULO ---

// 1. Recalculamos las tarifas para cada viajero
const updatedTravelerRates = megaJson.travelerRates.map(rate => {
  const { productName, age } = rate;
  const travelDays = megaJson.travelDays;

  if (parseInt(age) >= 90) {
    return { ...rate, productPrice: "-", rate: "-" };
  }

  const priceTable = priceTables[productName];
  if (!priceTable) return rate;

  // Buscamos el precio base por días
  const priceRow = priceTable.find(p => p.dias === travelDays);
  if (!priceRow) return rate;
  const basePrice = priceRow.precio;

  // Buscamos el incremento por edad
  const ageIncrementRow = ageIncrements.find(inc => 
    parseInt(age) >= inc.DESDE && parseInt(age) <= inc.HASTA
  );

  let finalPrice = basePrice;
  if (ageIncrementRow) {
    const incrementMultiplier = ageIncrementRow.INCREMENTO;
    // Fórmula: Base + (Base * Incremento)
    finalPrice = basePrice + (basePrice * incrementMultiplier);
  }

  return { 
    ...rate, 
    rate: Math.round(finalPrice), // Redondeo a entero para coincidir con tu sistema
    productPrice: basePrice.toFixed(2) 
  };
});

// 2. Recalculamos Totales en 'quotedProducts'
const updatedQuotedProducts = megaJson.quotedProducts.map(product => {
  const ratesForThisProduct = updatedTravelerRates.filter(r => r.productId === product.productId);
  const hasInvalidRate = ratesForThisProduct.some(r => r.rate === "-");

  if (hasInvalidRate) {
    return { ...product, total: "-" };
  } else {
    const newTotal = ratesForThisProduct.reduce((sum, r) => sum + (parseFloat(r.rate) || 0), 0);
    return { ...product, total: newTotal };
  }
});

// 3. Actualizamos 'groupedTravelerRates'
const updatedGroupedTravelerRates = {};
for (const productName in megaJson.groupedTravelerRates) {
    updatedGroupedTravelerRates[productName] = updatedTravelerRates.filter(rate => rate.productName === productName);
}

// 4. Salida Final
return {
  ...megaJson,
  travelerRates: updatedTravelerRates,
  quotedProducts: updatedQuotedProducts,
  groupedTravelerRates: updatedGroupedTravelerRates,
};
